from taf.rfrl.procedures.resources.python.bts.components.bts_component import BtsComponent
from taf.rfrl.procedures.resources.python.bts.utils.bts_types import ApiResponse
from taf.rfrl.procedures.resources.python.bts.utils.pretty_logger import log_info, log_debug


class Antenna(BtsComponent):
    """ Represents RMOD Antenna. """

    def __init__(self, parent: BtsComponent, antenna_info: ApiResponse):
        """
        :param parent: BTS component to which this Antenna belongs; usually it is RMOD
        :param antenna_info: information about this Antenna received as a response to API request;
                             must contain following data:
                             {'dist_names': {'config': 'MRBTS-1/EQM-1/APEQM-1/RMOD-1/PHYANT-1',
                                             'runtime': 'MRBTS-1/EQM_R-1/APEQM_R-1/RMOD_R-1/PHYANT_R-1'},
                              'id': '1',
                              'name': 'PHYANT'}
        """
        log_info('Creating new Antenna')
        super(Antenna, self).__init__(antenna_info['name'])
        self._parent = parent
        self._id = antenna_info['id']
        self._config_dist_name = antenna_info['dist_names']['config']
        self._runtime_dist_name = antenna_info['dist_names']['runtime']
        log_debug(f'Antenna details:\n'
                  f'name={self.name}\n'
                  f'id={self._id}\n'
                  f'config_dist_name={self._config_dist_name}\n'
                  f'runtime_dist_name={self._runtime_dist_name}\n'
                  f'parent={self._parent.name}')

    def __eq__(self, other):
        return self._name == other.name

    @property
    def rmod(self) -> BtsComponent:
        """ Returns RMOD to which this Antenna belongs. """
        return self._parent

    @property
    def runtime_dist_name(self) -> str:
        """ Returns runtime dist name of this Antenna, i.e. 'MRBTS-1/EQM_R-1/APEQM_R-1/RMOD_R-1/PHYANT_R-1'. """
        return self._runtime_dist_name

    @property
    def id(self) -> str:
        """ Returns ID of this Antenna, e.g. '1'. """
        return self._id
